WITH fp AS (SELECT e.* FROM RIPPLE.PHANTOM_EPISODES e WHERE e.VARIANT='all' AND NOT EXISTS (SELECT 1 FROM RIPPLE_GT.PHANTOM_EVENTS g WHERE e.STORE_ID=g.STORE_ID AND e.SKU_ID=g.SKU_ID AND e.ALERT_DATE BETWEEN g.START_DATE AND g.END_DATE + 1))
SELECT DAYS_BETWEEN(fp.LAST_DATE, fp.ONSET_DATE)+1 LEN, d.BOOK_SOD, d.BOOK_EOD, d.UNITS, d.SHORT_LINES, d.PICK_EX, d.STOCK_TICKETS, ROUND(s.P_PHANTOM,3) P, ROUND(s.LAMBDA_HAT,2) LAM, ROUND(s.LLR_SALES,2) LS, ROUND(s.LLR_OMS,2) LO
FROM fp JOIN RIPPLE.SKU_DAY d ON d.STORE_ID=fp.STORE_ID AND d.SKU_ID=fp.SKU_ID AND d.D=fp.ALERT_DATE
JOIN RIPPLE.PHANTOM_SCORES s ON s.VARIANT='all' AND s.STORE_ID=fp.STORE_ID AND s.SKU_ID=fp.SKU_ID AND s.D=fp.ALERT_DATE
ORDER BY RANDOM() LIMIT 15;
